const API_WHITELIST_ = [
  'loginUser', 'getInitialAppData', 'updateUserProfile', 'logAktivitasSiswa', 'getAktivitasList',
  'submitAktivitasSiswa', 'uploadTugasKelompok', 'submitEvaluasiDiri', 'getKelasMembers',
  'getForumPosts', 'postForumDiskusi', 'updateForumPost', 'deleteForumPost',
  'getForumGroups', 'createForumGroup', 'sendGroupMessage',
  'getTransaksiList', 'simpanNilaiGuru', 'simpanBadgeGuru', 'tambahMateriGuru', 'uploadMateriPdfGuru',
  'simpanPertemuanGuru', 'simpanBankSoal', 'getDaftarSiswaKelas', 'getHasilEvaluasiRekap', 'getEvaluasiDiriRekap'
];

function apiResponse_(action, payload) {
  let out;
  try {
    if (API_WHITELIST_.indexOf(String(action)) === -1) {
      out = { success: false, apiError: 'Aksi tidak dikenal: ' + action };
    } else {
      out = globalThis[String(action)](payload || {});
    }
  } catch (err) {
    out = { success: false, apiError: String(err && err.message ? err.message : err) };
  }
  return ContentService.createTextOutput(JSON.stringify(out)).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  let req = {};
  try { req = JSON.parse((e && e.postData && e.postData.contents) || '{}'); } catch (err) {}
  return apiResponse_(req.action, req.payload);
}

