/**
 * Helper membuat/mengisi sheet berdasarkan GID atau nama jika belum ada
 */
function ensureSheetWithHeaders_(ss, sheetName, headers, defaultRows, targetGid) {
  let sheet = getSheetByGidOrName_(ss, targetGid, sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
  }
  if (sheet.getLastRow() === 0) {
    sheet.getRange(1, 1, 1, headers.length).setValues([headers]).setFontWeight('bold');
    sheet.setFrozenRows(1);
    if (defaultRows && defaultRows.length > 0) {
      const padded = defaultRows.map(function(r) {
        const x = r.slice();
        while (x.length < headers.length) x.push('');
        return x;
      });
      sheet.getRange(2, 1, padded.length, headers.length).setValues(padded);
    }
  }
  return sheet;
}

/**
 * Tambah kolom header yang belum ada pada sheet lama (migrasi otomatis)
 */
function ensureColumns_(sheet, cols) {
  if (!sheet || sheet.getLastRow() === 0) return;
  const lastCol = sheet.getLastColumn();
  const headers = sheet.getRange(1, 1, 1, lastCol).getValues()[0].map(function(h) { return String(h || '').trim(); });
  cols.forEach(function(c) {
    if (headers.indexOf(c) === -1) {
      sheet.getRange(1, headers.length + 1).setValue(c).setFontWeight('bold');
      headers.push(c);
    }
  });
}

function ensurePertemuanSheet_(ss) {
  let sh = ss.getSheetByName(SHEET_NAMES.PERTEMUAN);
  if (!sh) {
    sh = ss.insertSheet(SHEET_NAMES.PERTEMUAN);
    sh.getRange(1, 1, 1, 8).setValues([['Pertemuan_ID', 'Nama_Pertemuan', 'Judul_Pertemuan', 'Tanggal', 'Rangkuman', 'Dibuat_Oleh', 'Dibuat_Pada', 'Tujuan_Pembelajaran']]).setFontWeight('bold');
    sh.setFrozenRows(1);
  }
  // Migrasi otomatis: tambahkan kolom Tujuan_Pembelajaran pada sheet lama
  ensureColumns_(sh, ['Tujuan_Pembelajaran']);
  return sh;
}

/**
 * Helper Serialisasi Data Anti-Blank (Mengubah Date -> String ISO & cell kosong -> "")
 */
function cleanData(sheet) {
  if (!sheet || sheet.getLastRow() < 2) return [];
  const tz = Session.getScriptTimeZone() || 'Asia/Jakarta';
  const values = sheet.getDataRange().getValues();
  const headers = values[0].map(function(h) { return String(h || '').trim(); });
  const result = [];

  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    const isRowEmpty = row.every(function(cell) { return cell === '' || cell === null || cell === undefined; });
    if (isRowEmpty) continue;

    const obj = {};
    for (let j = 0; j < headers.length; j++) {
      const key = headers[j];
      if (!key) continue;
      const val = row[j];
      if (val instanceof Date) {
        if (isNaN(val.getTime())) {
          obj[key] = '';
        } else {
          obj[key] = Utilities.formatDate(val, tz, 'yyyy-MM-dd HH:mm');
        }
      } else if (val === null || val === undefined) {
        obj[key] = '';
      } else {
        obj[key] = val;
      }
    }
    result.push(obj);
  }
  return result;
}

/**
 * Sheet Aktivitas: dibuat otomatis bila belum ada agar tidak ada aktivitas siswa yang terlewat
 */
function getAktivitasSheet_(ss) {
  let sh = ss.getSheetByName(SHEET_NAMES.AKTIVITAS);
  if (!sh) {
    sh = ss.insertSheet(SHEET_NAMES.AKTIVITAS);
    sh.getRange(1, 1, 1, 6).setValues([['ID_Aktivitas', 'Nama_Siswa', 'Deskripsi_Aktivitas', 'Tanggal_Waktu', 'User_ID', 'Jenis_Aktivitas']]).setFontWeight('bold');
    sh.setFrozenRows(1);
  }
  return sh;
}

function aktKategori_(jenis) {
  const j = String(jenis || '');
  if (j === 'Mengerjakan Kuis' || j === 'Mengumpulkan Tugas') return 'trx';
  if (j === 'Refleksi' || j === 'Evaluasi Diri') return 'ref';
  if (j === 'Forum Diskusi') return 'forum';
  return '';
}

function aktWaktu_(v) {
  const t = String(v || '').trim();
  return t.length === 16 ? (t + ':00') : t;
}

/**
 * Gabungan Aktivitas: catatan sheet Aktivitas + aktivitas yang tercatat di Transaksi_Belajar,
 * Hasil Evaluasi/Refleksi, dan Forum_Diskusi namun belum ada di sheet Aktivitas (pengaman agar
 * SEMUA aktivitas siswa pasti tampil di portal guru). Hasil: urut lama -> baru.
 */
function buildAktivitasGabungan_(ss) {
  const base = cleanData(getAktivitasSheet_(ss));
  const have = {};
  base.forEach(function(a) {
    const k = aktKategori_(a.Jenis_Aktivitas);
    if (k) have[String(a.User_ID || '').trim() + '|' + String(a.Tanggal_Waktu || '').slice(0, 16) + '|' + k] = true;
  });
  const extra = [];
  const add = function(uid, nama, desc, waktu, jenis, idSrc) {
    const k = aktKategori_(jenis);
    const key = String(uid || '').trim() + '|' + String(waktu || '').slice(0, 16) + '|' + k;
    if (!uid || have[key]) return;
    have[key] = true;
    extra.push({
      ID_Aktivitas: 'AKT-SYNC-' + idSrc,
      Nama_Siswa: String(nama || ''),
      Deskripsi_Aktivitas: desc,
      Tanggal_Waktu: aktWaktu_(waktu),
      User_ID: String(uid),
      Jenis_Aktivitas: jenis
    });
  };

  try {
    cleanData(getSheetByGidOrName_(ss, SHEET_GIDS.TRANSAKSI_LMS, SHEET_NAMES.TRANSAKSI)).forEach(function(t) {
      const j = String(t.Jenis_Aktivitas || '');
      const sc = (t.Nilai_Guru !== '' && t.Nilai_Guru !== null) ? t.Nilai_Guru : t.Skor_Otomatis;
      if (j.indexOf('Kuis') !== -1 && sc !== '' && sc !== null) {
        add(t.User_ID, t.Nama_Siswa, 'Mengerjakan ' + j + ' dengan skor ' + sc + '/100', t.Tanggal, 'Mengerjakan Kuis', t.TRX_ID);
      } else {
        add(t.User_ID, t.Nama_Siswa, 'Mengumpulkan jawaban ' + j, t.Tanggal, 'Mengumpulkan Tugas', t.TRX_ID);
      }
    });
  } catch (e) {}

  try {
    cleanData(getSheetByGidOrName_(ss, SHEET_GIDS.HASIL_EVALUASI, SHEET_NAMES.EVALUASI_DIRI)).forEach(function(e) {
      if (String(e.Jenis_Evaluasi || '').trim() !== '') return; // baris evaluasi sudah tercakup oleh Transaksi
      add(e.User_ID, e.Nama_Siswa, 'Mengisi Refleksi (Skala Pemahaman: ' + e.Skala_Pemahaman + '/5)', e.Tanggal, 'Refleksi', e.Eval_ID);
    });
  } catch (e) {}

  try {
    const forum = ss.getSheetByName(SHEET_NAMES.FORUM);
    cleanData(forum).forEach(function(f) {
      if (String(f.Role || '').toLowerCase() !== 'siswa') return;
      const desc = f.Parent_ID
        ? ('Membalas diskusi pada topik: "' + String(f.Topik || '').replace(/^Balasan:\s*/i, '') + '"')
        : ('Membuat topik diskusi: "' + f.Topik + '"');
      add(f.User_ID, f.Nama_Pengirim, desc, f.Tanggal, 'Forum Diskusi', f.Post_ID);
    });
  } catch (e) {}

  const all = base.map(function(a, i) { return { a: a, i: i }; }).concat(extra.map(function(a, i) { return { a: a, i: 100000 + i }; }));
  all.sort(function(x, y) {
    const tx = String(x.a.Tanggal_Waktu || '').slice(0, 16), ty = String(y.a.Tanggal_Waktu || '').slice(0, 16);
    if (tx < ty) return -1;
    if (tx > ty) return 1;
    return x.i - y.i;
  });
  return all.map(function(o) { return o.a; });
}

/**
 * Perkaya detail jawaban Kuis Evaluasi dengan kunci & status benar/salah per soal
 */
function enrichDetailEvaluasi_(ss, jenis, detailStr) {
  const out = { detail: String(detailStr || ''), benar: '', total: '' };
  if (String(jenis || '') !== 'Kuis Evaluasi' || !out.detail) return out;
  try {
    const arr = JSON.parse(out.detail);
    if (!Array.isArray(arr)) return out;
    const soal = {};
    cleanData(ss.getSheetByName(SHEET_NAMES.BANK_SOAL)).forEach(function(q) { soal[String(q.Soal_ID)] = q; });
    let benar = 0;
    const items = arr.map(function(it) {
      const q = soal[String(it.q)] || {};
      const ok = String(it.a || '') !== '' && String(it.a) === String(q.Kunci_Jawaban || '');
      if (ok) benar++;
      return { q: it.q, a: it.a, k: q.Kunci_Jawaban || '', ok: ok };
    });
    out.detail = JSON.stringify(items);
    out.benar = benar;
    out.total = items.length;
  } catch (e) {}
  return out;
}

/**
 * Sinkronkan transaksi Evaluasi (Kuis Evaluasi & Studi Kasus) yang belum ada di sheet gid=1495900482
 */
function sinkronEvaluasiTertinggal_(ss) {
  const trxSheet = getSheetByGidOrName_(ss, SHEET_GIDS.TRANSAKSI_LMS, SHEET_NAMES.TRANSAKSI);
  const evalSheet = getSheetByGidOrName_(ss, SHEET_GIDS.HASIL_EVALUASI, SHEET_NAMES.EVALUASI_DIRI);
  if (!trxSheet || !evalSheet) return 0;
  ensureColumns_(trxSheet, ['Detail_Jawaban']);
  ensureColumns_(evalSheet, EVAL_COLS_);
  const have = {};
  cleanData(evalSheet).forEach(function(e) { have[String(e.Eval_ID || '').trim()] = true; });
  const headers = evalSheet.getRange(1, 1, 1, evalSheet.getLastColumn()).getValues()[0].map(function(h) { return String(h || '').trim(); });
  const rows = [];
  cleanData(trxSheet).forEach(function(t) {
    const j = String(t.Jenis_Aktivitas || '');
    const isEv = String(t.Pertemuan || '') === 'Evaluasi' || j.indexOf('Evaluasi') !== -1 || j.indexOf('Studi Kasus') !== -1;
    if (!isEv || have[String(t.TRX_ID || '').trim()]) return;
    const nilai = (t.Nilai_Guru !== '' && t.Nilai_Guru !== null) ? t.Nilai_Guru : t.Skor_Otomatis;
    const rich = enrichDetailEvaluasi_(ss, j, t.Detail_Jawaban);
    const map = {
      Eval_ID: t.TRX_ID, Tanggal: t.Tanggal, User_ID: t.User_ID, Nama_Siswa: t.Nama_Siswa,
      Skala_Pemahaman: '', Materi_Paling_Dikuasai: j, Kendala_Belajar: t.Jawaban_Atau_FileURL,
      Jenis_Evaluasi: j, Pertemuan: t.Pertemuan || 'Evaluasi', Nilai: nilai, Status: t.Status,
      Feedback_Guru: t.Feedback_Guru, Detail_Jawaban: rich.detail, Jumlah_Benar: rich.benar, Jumlah_Soal: rich.total
    };
    rows.push(headers.map(function(h) { return Object.prototype.hasOwnProperty.call(map, h) ? map[h] : ''; }));
  });
  if (rows.length) {
    evalSheet.getRange(evalSheet.getLastRow() + 1, 1, rows.length, headers.length).setValues(rows);
    SpreadsheetApp.flush();
  }
  return rows.length;
}

/** Dapat dijalankan manual dari editor Apps Script untuk menyelaraskan data evaluasi lama */
function sinkronkanEvaluasi() {
  return { success: true, ditambahkan: sinkronEvaluasiTertinggal_(getTargetSpreadsheet_()) };
}

function newAktId_(offset) {
  return 'AKT-' + (Date.now() + (offset || 0)) + '-' + Math.floor(100 + Math.random() * 900);
}

function nowFormatted_() {
  const tz = Session.getScriptTimeZone() || 'Asia/Jakarta';
  return Utilities.formatDate(new Date(), tz, 'yyyy-MM-dd HH:mm:ss');
}

/**
 * Helper menambahkan baris secara dinamis mengikuti header yang ada di sheet target
 */
function appendRowByHeaderMap_(sheet, dataMap, fallbackOrderedArray) {
  if (!sheet) return;
  if (sheet.getLastRow() === 0) {
    sheet.appendRow(fallbackOrderedArray);
    return;
  }
  const lastCol = sheet.getLastColumn();
  const headers = sheet.getRange(1, 1, 1, lastCol).getValues()[0].map(function(h) {
    return String(h || '').trim();
  });
  const newRow = headers.map(function(h, idx) {
    if (Object.prototype.hasOwnProperty.call(dataMap, h)) {
      return dataMap[h];
    }
    return fallbackOrderedArray[idx] !== undefined ? fallbackOrderedArray[idx] : '';
  });
  sheet.appendRow(newRow);
}

/**
 * Autentikasi Pengguna:
 * - Memeriksa Data Siswa pada gid=0
 * - Memeriksa Akun Akses Demo pada gid=2025841044
 */
function loginUser(payload) {
  try {
    if (!payload || !payload.email || !payload.password) {
      return { success: false, message: 'Email dan password wajib diisi.' };
    }
    const email = String(payload.email).trim().toLowerCase();
    const password = String(payload.password).trim();
    const ss = getTargetSpreadsheet_();

    // 1. Cek di sheet Data_Siswa (gid=0) terlebih dahulu
    const siswaSheet = getSheetByGidOrName_(ss, SHEET_GIDS.DATA_SISWA, SHEET_NAMES.DATA_SISWA);
    const siswaList = cleanData(siswaSheet);
    for (let i = 0; i < siswaList.length; i++) {
      const s = siswaList[i];
      const sEmail = String(s['Email'] || s['Username'] || '').trim().toLowerCase();
      if (sEmail === email) {
        const sPass = String(s['Password'] || '').trim();
        if (sPass && sPass !== password) {
          return { success: false, message: 'Password yang Anda masukkan salah.' };
        }
        const sId = String(s['ID Siswa'] || s['User_ID'] || s['ID'] || ('SISWA-' + (i + 1)));
        const sNama = String(s['Nama Siswa'] || s['Nama'] || s['Nama_Lengkap'] || 'Siswa MPLB');
        return {
          success: true,
          user: {
            user_id: sId,
            id: sId,
            username: sEmail,
            email: sEmail,
            nama: sNama,
            role: 'Siswa',
            kelas: String(s['Kelas'] || 'XI MPLB 1'),
            avatar: String(s['Avatar'] || 'siswa-1')
          }
        };
      }
    }

    // 2. Cek di sheet Akses Demo / Users (gid=2025841044)
    const usersSheet = getSheetByGidOrName_(ss, SHEET_GIDS.USERS_DEMO, SHEET_NAMES.USERS);
    const usersList = cleanData(usersSheet);
    for (let j = 0; j < usersList.length; j++) {
      const u = usersList[j];
      const uEmail = String(u['Email'] || u['Username'] || '').trim().toLowerCase();
      if (uEmail === email) {
        const uPass = String(u['Password'] || '').trim();
        if (uPass && uPass !== password) {
          return { success: false, message: 'Password yang Anda masukkan salah.' };
        }
        const uId = String(u['ID'] || u['User_ID'] || ('DEMO-' + (j + 1)));
        const uNama = String(u['Nama'] || u['Nama_Lengkap'] || 'Pengguna Demo');
        const uRole = String(u['Role'] || 'Siswa');
        return {
          success: true,
          user: {
            user_id: uId,
            id: uId,
            username: uEmail,
            email: uEmail,
            nama: uNama,
            role: uRole,
            kelas: String(u['Kelas'] || (uRole.toLowerCase() === 'guru' ? 'Guru Pengampu' : 'XI MPLB 1')),
            avatar: String(u['Avatar'] || (uRole.toLowerCase() === 'guru' ? 'guru-1' : 'siswa-1'))
          }
        };
      }
    }

    return { success: false, message: 'Email belum terdaftar. Hubungi gurumu jika belum memiliki akun.' };
  } catch (e) {
    return { success: false, message: 'Terjadi kesalahan server: ' + e.message };
  }
}

/**
 * Memuat Data Awal Workspace dari Spreadsheet Target & GID Spesifik
 */
function getInitialAppData(payload) {
  try {
    const ss = getTargetSpreadsheet_();
    const userId = payload && payload.userId ? String(payload.userId).trim() : '';

    const materi = cleanData(ss.getSheetByName(SHEET_NAMES.MATERI));
    const bankSoal = cleanData(ss.getSheetByName(SHEET_NAMES.BANK_SOAL));
    const allTrx = cleanData(getSheetByGidOrName_(ss, SHEET_GIDS.TRANSAKSI_LMS, SHEET_NAMES.TRANSAKSI));
    const allEval = cleanData(getSheetByGidOrName_(ss, SHEET_GIDS.HASIL_EVALUASI, SHEET_NAMES.EVALUASI_DIRI));
    const aktivitas = buildAktivitasGabungan_(ss);
    const badgeRecords = cleanData(ss.getSheetByName(SHEET_NAMES.BADGE_SISWA));
    const pertemuan = cleanData(ensurePertemuanSheet_(ss));

    const userTransactions = userId
      ? allTrx.filter(function(t) { return String(t.User_ID || '').trim() === userId; }).reverse()
      : [];

    const userEvalList = userId
      ? allEval.filter(function(e) { return String(e.User_ID || '').trim() === userId; })
      : [];
    const userEvaluasiDiri = userEvalList.length > 0 ? userEvalList[userEvalList.length - 1] : null;

    return {
      success: true,
      materi: materi,
      pertemuan: pertemuan,
      bankSoal: bankSoal,
      userTransactions: userTransactions,
      userEvaluasiDiri: userEvaluasiDiri,
      aktivitas: aktivitas.slice().reverse(),
      badgeRecords: badgeRecords,
      stats: {
        totalMateri: materi.length,
        totalSoal: bankSoal.length,
        totalTransaksi: allTrx.length,
        pendingPenilaian: allTrx.filter(function(t) { return String(t.Status || '') !== 'Dinilai' && String(t.Status || '').indexOf('Selesai') === -1; }).length,
        totalEvaluasiDiri: allEval.length,
        totalAktivitas: aktivitas.length
      }
    };
  } catch (e) {
    return { success: false, message: e.message };
  }
}

/**
 * Perbarui Profil Pengguna pada gid=2025841044 & gid=0
 */
function updateUserProfile(payload) {
  try {
    const ss = getTargetSpreadsheet_();
    const userId = String(payload.userId || '').trim();
    const nama = String(payload.nama || '').trim();
    const email = String(payload.email || '').trim().toLowerCase();
    const password = String(payload.password || '').trim();
    const kelas = String(payload.kelas || '').trim();
    const avatar = String(payload.avatar || 'siswa-1').trim();

    let updatedRole = 'Siswa';

    const usersSheet = getSheetByGidOrName_(ss, SHEET_GIDS.USERS_DEMO, SHEET_NAMES.USERS);
    if (usersSheet && usersSheet.getLastRow() >= 2) {
      const range = usersSheet.getDataRange();
      const values = range.getValues();
      for (let i = 1; i < values.length; i++) {
        if (String(values[i][0] || '').trim() === userId) {
          values[i][1] = email;
          values[i][2] = password;
          values[i][3] = nama;
          updatedRole = String(values[i][4] || 'Siswa');
          values[i][5] = kelas;
          values[i][6] = avatar;
          range.setValues(values);
          break;
        }
      }
    }

    const siswaSheet = getSheetByGidOrName_(ss, SHEET_GIDS.DATA_SISWA, SHEET_NAMES.DATA_SISWA);
    if (siswaSheet && siswaSheet.getLastRow() >= 2) {
      const sRange = siswaSheet.getDataRange();
      const sValues = sRange.getValues();
      for (let j = 1; j < sValues.length; j++) {
        if (String(sValues[j][0] || '').trim() === userId) {
          sValues[j][1] = nama;
          sValues[j][2] = email;
          sValues[j][3] = kelas;
          sValues[j][5] = password;
          sValues[j][6] = avatar;
          sRange.setValues(sValues);
          break;
        }
      }
    }

    return {
      success: true,
      user: {
        user_id: userId,
        nama: nama,
        email: email,
        username: email,
        password: password,
        kelas: kelas,
        avatar: avatar,
        role: updatedRole
      }
    };
  } catch (e) {
    return { success: false, message: e.message };
  }
}

