/**
 * Unggah File Tugas Kelompok (Kolaborasi Kelompok) ke Google Drive & catat ke gid=245669689
 * Payload: userId, namaSiswa, namaKelompok, catatan, fileName, mimeType, base64Data
 * File disimpan di Drive: EduSpace_Tugas_Kelompok_MPLB / <Nama Kelompok>
 * Catatan: wajib otorisasi akses Drive saat pertama kali dijalankan.
 */
function uploadTugasKelompok(payload) {
  const lock = LockService.getScriptLock();
  try {
    if (!payload || !payload.base64Data) return { success: false, message: 'File tugas kosong.' };

    const MAX_BYTES = 8 * 1024 * 1024;
    const ALLOWED = ['pdf', 'doc', 'docx', 'ppt', 'pptx', 'xls', 'xlsx', 'jpg', 'jpeg', 'png', 'zip'];
    const rawName = String(payload.fileName || 'Tugas_Kelompok.pdf');
    const safeName = rawName.replace(/[\\\/:*?"<>|]/g, '_');
    const ext = (safeName.split('.').pop() || '').toLowerCase();
    if (ALLOWED.indexOf(ext) === -1) {
      return { success: false, message: 'Format file tidak didukung. Gunakan PDF, Word, PowerPoint, Excel, JPG, PNG, atau ZIP.' };
    }

    const bytes = Utilities.base64Decode(payload.base64Data);
    if (bytes.length > MAX_BYTES) return { success: false, message: 'Ukuran file maksimal 8 MB.' };

    lock.waitLock(20000);

    const ss = getTargetSpreadsheet_();
    const trxSheet = getSheetByGidOrName_(ss, SHEET_GIDS.TRANSAKSI_LMS, SHEET_NAMES.TRANSAKSI);
    const aktSheet = getAktivitasSheet_(ss);
    ensureColumns_(trxSheet, ['Detail_Jawaban']);

    const namaKelompok = String(payload.namaKelompok || '-').trim() || '-';
    const rootName = 'EduSpace_Tugas_Kelompok_MPLB';
    const rootIt = DriveApp.getFoldersByName(rootName);
    const root = rootIt.hasNext() ? rootIt.next() : DriveApp.createFolder(rootName);
    const subName = namaKelompok.replace(/[\\\/:*?"<>|]/g, '_').slice(0, 80);
    const subIt = root.getFoldersByName(subName);
    const folder = subIt.hasNext() ? subIt.next() : root.createFolder(subName);

    const blob = Utilities.newBlob(bytes, payload.mimeType || 'application/octet-stream', safeName);
    const file = folder.createFile(blob);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
    const fileUrl = file.getUrl();

    const trxId = 'TRX-' + Utilities.formatDate(new Date(), 'Asia/Jakarta', 'yyyyMMdd') + '-' + String(Math.floor(1000 + Math.random() * 9000));
    const tanggal = nowFormatted_();
    const catatan = String(payload.catatan || '').trim();
    // URL file diletakkan paling depan agar tombol "Buka Tautan" pada panel guru langsung berfungsi
    const jawabanText = fileUrl + (catatan ? (' | Catatan: ' + catatan) : '');

    const row = {
      TRX_ID: trxId,
      Tanggal: tanggal,
      User_ID: String(payload.userId || ''),
      Nama_Siswa: String(payload.namaSiswa || ''),
      Pertemuan: 'Pertemuan 2',
      Jenis_Aktivitas: 'Kolaborasi Kelompok',
      Jawaban_Atau_FileURL: jawabanText,
      Nama_Kelompok: namaKelompok,
      Skor_Otomatis: '',
      Nilai_Guru: '',
      Feedback_Guru: '',
      Status: 'Menunggu Penilaian',
      Detail_Jawaban: JSON.stringify({ file: safeName, fileId: file.getId(), fileUrl: fileUrl })
    };
    appendRowByHeaderMap_(trxSheet, row, [
      trxId, tanggal, row.User_ID, row.Nama_Siswa, 'Pertemuan 2', 'Kolaborasi Kelompok',
      jawabanText, namaKelompok, '', '', '', 'Menunggu Penilaian'
    ]);

    const aktId = newAktId_();
    const desc = 'Mengumpulkan tugas Kolaborasi Kelompok (' + namaKelompok + ') — File: ' + safeName;
    if (aktSheet) {
      aktSheet.appendRow([aktId, row.Nama_Siswa, desc, tanggal, row.User_ID, 'Mengumpulkan Tugas']);
    }

    SpreadsheetApp.flush();

    return {
      success: true,
      item: row,
      aktivitasItem: {
        ID_Aktivitas: aktId,
        Nama_Siswa: row.Nama_Siswa,
        Deskripsi_Aktivitas: desc,
        Tanggal_Waktu: tanggal,
        User_ID: row.User_ID,
        Jenis_Aktivitas: 'Mengumpulkan Tugas'
      }
    };
  } catch (e) {
    return { success: false, message: 'Gagal mengunggah file: ' + e.message };
  } finally {
    try { lock.releaseLock(); } catch (e2) {}
  }
}

