/**
 * Panel Guru: Upload PDF Materi ke Google Drive (folder "EduSpace Materi") lalu tautkan ke Folder Pertemuan
 * Catatan: wajib otorisasi akses Drive saat pertama kali dijalankan.
 */
function uploadMateriPdfGuru(payload) {
  try {
    if (!payload || !payload.base64) return { success: false, message: 'File PDF kosong.' };
    const folderName = 'EduSpace Materi';
    const it = DriveApp.getFoldersByName(folderName);
    const root = it.hasNext() ? it.next() : DriveApp.createFolder(folderName);
    const pName = String(payload.pertemuan || 'Pertemuan');
    const sub = root.getFoldersByName(pName);
    const folder = sub.hasNext() ? sub.next() : root.createFolder(pName);

    const blob = Utilities.newBlob(Utilities.base64Decode(payload.base64), 'application/pdf', String(payload.fileName || 'materi.pdf'));
    const file = folder.createFile(blob);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

    const item = simpanMateriRow_(payload, file.getId(), 'file', file.getUrl());
    return { success: true, item: item };
  } catch (e) {
    return { success: false, message: 'Gagal mengunggah PDF: ' + e.message };
  }
}

/**
 * Panel Guru: Tambah / Edit Folder Pertemuan + Rangkuman
 */
function simpanPertemuanGuru(payload) {
  try {
    const ss = getTargetSpreadsheet_();
    const sheet = ensurePertemuanSheet_(ss);
    const nama = String(payload.nama || '').trim();
    if (!nama) return { success: false, message: 'Nama pertemuan wajib diisi.' };

    const row = {
      Nama_Pertemuan: nama,
      Judul_Pertemuan: String(payload.judul || ''),
      Tanggal: String(payload.tanggal || ''),
      Tujuan_Pembelajaran: String(payload.tujuan || ''),
      Rangkuman: String(payload.rangkuman || '')
    };
    const toItem = function(id) {
      return { Pertemuan_ID: id, Nama_Pertemuan: row.Nama_Pertemuan, Judul_Pertemuan: row.Judul_Pertemuan, Tanggal: row.Tanggal, Tujuan_Pembelajaran: row.Tujuan_Pembelajaran, Rangkuman: row.Rangkuman };
    };

    // Posisi kolom dicari lewat nama header agar aman terhadap urutan kolom
    const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0].map(function(h) { return String(h || '').trim(); });
    const colTujuan = headers.indexOf('Tujuan_Pembelajaran');

    if (payload.mode === 'edit' && payload.id && sheet.getLastRow() >= 2) {
      const range = sheet.getDataRange();
      const values = range.getValues();
      for (let i = 1; i < values.length; i++) {
        if (String(values[i][0] || '').trim() === String(payload.id).trim()) {
          const oldNama = String(values[i][1] || '');
          values[i][1] = row.Nama_Pertemuan;
          values[i][2] = row.Judul_Pertemuan;
          values[i][3] = row.Tanggal;
          values[i][4] = row.Rangkuman;
          if (colTujuan !== -1) values[i][colTujuan] = row.Tujuan_Pembelajaran;
          range.setValues(values);
          if (oldNama && oldNama !== nama) {
            const ms = ss.getSheetByName(SHEET_NAMES.MATERI);
            if (ms && ms.getLastRow() >= 2) {
              const mr = ms.getDataRange(); const mv = mr.getValues();
              for (let k = 1; k < mv.length; k++) { if (String(mv[k][1]) === oldNama) mv[k][1] = nama; }
              mr.setValues(mv);
            }
          }
          return { success: true, item: toItem(String(payload.id)) };
        }
      }
    }

    const id = 'PRT-' + Date.now();
    const newRow = [id, row.Nama_Pertemuan, row.Judul_Pertemuan, row.Tanggal, row.Rangkuman, String(payload.guruNama || 'Guru'), nowFormatted_()];
    while (newRow.length < headers.length) newRow.push('');
    if (colTujuan !== -1) newRow[colTujuan] = row.Tujuan_Pembelajaran;
    sheet.appendRow(newRow);
    return { success: true, item: toItem(id) };
  } catch (e) {
    return { success: false, message: e.message };
  }
}

